import socket, struct

def rpc_call(host, port, prog, vers, proc, data=b''):
    xid = 1
    msg = struct.pack(">IIIIIIII", xid, 0, 2, prog, vers, proc, 0, 0) + data
    rm = struct.pack(">I", len(msg) | 0x80000000)
    s = socket.socket()
    s.settimeout(4)
    try:
        s.connect((host, port))
        s.sendall(rm + msg)
        hdr = b''
        while len(hdr) < 4:
            chunk = s.recv(4-len(hdr))
            if not chunk: break
            hdr += chunk
        if len(hdr) == 4:
            n = struct.unpack(">I", hdr)[0] & 0x7fffffff
            body = b''
            while len(body) < n:
                chunk = s.recv(n-len(body))
                if not chunk: break
                body += chunk
            return body
        return b'<no header>'
    except Exception as e:
        return ('EXC', repr(e))
    finally:
        s.close()

for proc,label in [(3,"GETPORT"), (4,"DUMP")]:
    r = rpc_call("172.29.0.1", 111, 100000, 2, proc)
    if isinstance(r, tuple):
        print(label, r)
